"""Builds annotation_report.md and annotation_paper_paragraphs.tex from annotation_results/*.csv (run after annotation_analysis.py)."""
import json
from pathlib import Path
import pandas as pd

ROOT = Path(r'C:\Users\PC\Desktop\Programs\MediViHall')
R = ROOT / 'annotation_results'
rd = lambda n: pd.read_csv(R / n)
H = json.loads((R / 'headline_numbers.json').read_text(encoding='utf-8'))


def ci(s):
    lo, hi = s.split('..')
    return float(lo), float(hi)


def f(v, c=None, d=3):
    t = f'{v:.{d}f}'
    if c:
        lo, hi = ci(c) if isinstance(c, str) else c
        t += f' [{lo:.{d}f}, {hi:.{d}f}]'
    return t


A1, A3, A5 = rd('A1_score_agreement_overall.csv'), rd('A3_flag_agreement_overall.csv'), rd('A5_agreement_by_annotator_type.csv')
A2, A4 = rd('A2_score_agreement_by_modality.csv'), rd('A4_flag_agreement_by_modality.csv')
B1, B2, B4 = rd('B1_judge_vs_human_per_class.csv'), rd('B2_overall_any_hallucination_and_targets.csv'), rd('B4_primary_class_confusion.csv')
B5 = rd('B5_worst20_disagreements.csv')
C1, C2 = rd('C1_smhr_by_model_assumed_vs_equal.csv'), rd('C2_weight_sensitivity_summary.csv')
D1, D2, D3, D4, D5, D6 = [rd(n) for n in ['D1_annotator_means_by_modality.csv', 'D2_specialist_own_modality_vs_others_wilcoxon.csv',
                                           'D3_annotator_agreement_with_majority_and_judge.csv', 'D4_student_vs_specialists.csv',
                                           'D5_leniency_bland_altman.csv', 'D6_annotator_rating_vs_item_smhr.csv']]
E1 = rd('E1_annotator_factual_vs_item_smhr.csv')
n_items = H['n_items']
n_j = H['judge_labels_found']
a1 = A1.set_index('dimension')
a3 = A3.set_index('class')
b1 = B1.set_index('class')
b2 = B2.set_index(['scope', 'judge_output'])
c2 = C2.set_index('weight_set')
d4 = D4.set_index('dimension')
e1 = E1.set_index('scope')


def md_table(df, cols=None, rename=None):
    df = df[cols] if cols else df
    if rename:
        df = df.rename(columns=rename)
    head = '| ' + ' | '.join(map(str, df.columns)) + ' |\n|' + '---|' * len(df.columns) + '\n'
    return head + '\n'.join('| ' + ' | '.join(str(x) for x in r) + ' |' for r in df.itertuples(index=False))


# ---------------------------------------------------------------- pieces
comb = b2.xs('combined_any (pipeline: any class)', level='judge_output')
l1 = b2.xs('layer1_any (omission/fabrication signal)', level='judge_output')
l2 = b2.xs('layer2_any (any claim hallucination)', level='judge_output')
by_type_fact = A5[A5.measure == 'factual_correctness'].set_index('pair_type')
by_type_flag = A5[A5.measure == 'FLAGS'].set_index('pair_type')
by_type_comp = A5[A5.measure == 'completeness'].set_index('pair_type')
sig = D2[D2.holm_p_24_tests < 0.05]
derm_f = D2[(D2.specialist == 'dermatology_specialist') & (D2.dimension == 'factual_correctness')].iloc[0]
rad_s = D2[(D2.specialist == 'radiology_specialist') & (D2.dimension == 'clinical_safety')].iloc[0]
stu = D4.set_index('dimension')
d3 = D3.set_index('annotator')

_fm = D1[D1.dimension == 'factual_correctness']['mean']
fm_lo, fm_hi = _fm.min(), _fm.max()
report = f"""# MedViHall annotation analysis

*Generated by `annotation_analysis.py` (bootstrap: 2,000 resamples of items, seed 42; n reported for every number).*

> ## What can and cannot be claimed in the paper
> **Provenance of the annotation set (state this plainly in the paper).** The six annotation files analysed here were supplied by the project
> owner as the human annotation set. The repository history shows them first committed as `ai_annotations/` by Claude sessions and later renamed
> to `human_annotations/`; their contents are byte-identical to the `annotations_ai_*.jsonl` files. This analysis uses them as the annotator
> set because it was instructed to, and describes the annotators only by the roles in the files (generalist, four modality specialists,
> undergraduate student). **If the files are not independent human work, the paper must say so, and the sections below do not support a
> claim of clinician validation.**
>
> **Can be claimed (with the stated caveats):** the six annotators agree strongly on the 0-5 scores (ICC(2,k) {f(a1.ICC2_k.min(),None)}-{f(a1.ICC2_k.max(),None)}) and only moderately on the hallucination flags, with OMISSION, ANATOMICAL_CONFUSION and CLINICAL_REASONING_ERROR the least reliable classes; the automatic pipeline's item-level "any hallucination" label reaches F1 {f(comb.loc['ALL','F1'], comb.loc['ALL','F1_ci'])} against the annotator majority, just under the 0.90 target, while its class-level labels do not reach the targets; the SMHR ranking and the all-specialists-SRI>1 result are robust to the class weights.
>
> **Cannot be claimed:** that clinicians validated the judge, weights or metric; human inter-rater reliability; validation of the SMHR weights against clinicians (no elicitation data exist); generalisation beyond this sample (**{n_items} items rest on only 48 distinct images, 15 texts per image, and the 12 radiology images are the same file**, so items are clustered and the intervals, which resample items as independent, are optimistic); any statement about individual hallucination classes 3-6 as validated.

## Data
- {n_items} items, 4 modalities x 180; six complete annotators ({', '.join(H['annotators'])}); the incomplete `generalist_medium_effort` run (570 items, same annotator id) is excluded.
- Scores: factual_correctness, completeness, clinical_safety, informativeness, clarity, overall (0.0-5.0); flags: the 7 classes.
- Pipeline labels found for {n_j} of {n_items} items; the other {len(H['judge_labels_missing_items'])} have no usable pipeline label ({'; '.join(f'{v} x {k}' for k, v in H['judge_labels_missing_reasons'].items())}) and are excluded from B and E only. Baseline labels for four models are the core-run labels; the llava_med baseline, RAG and contrastive labels come from the Pillar B labeling run, and a response identical to the core-run response reuses the core label.
- Scores are low and compressed (mean factual_correctness {fm_lo:.1f}-{fm_hi:.1f} of 5 by annotator and modality) and the flags are common (OMISSION and FABRICATION are flagged on 26% and 59% of annotator ratings); both lower kappa-type statistics and inflate percent agreement.

## A. Agreement among annotators
**Finding: the six annotators agree strongly on the scores (single-rater ICC(2,1) {f(a1.ICC2_1.min())}-{f(a1.ICC2_1.max())}) and only moderately on the hallucination flags (mean pairwise kappa {f(A3.mean_pairwise_cohen_kappa.min())}-{f(A3.mean_pairwise_cohen_kappa.max())} by class).**

{md_table(A1.assign(ICC2_1=A1.apply(lambda r: f(r.ICC2_1, r.ICC2_1_ci), axis=1), ICC2_k=A1.apply(lambda r: f(r.ICC2_k, r.ICC2_k_ci), axis=1), alpha=A1.apply(lambda r: f(r.alpha_interval, r.alpha_ci), axis=1), QWK=A1.apply(lambda r: f(r['QWK_mean_pairwise_0.5bins'], r.QWK_ci), axis=1)), ['dimension', 'n_items', 'ICC2_1', 'ICC2_k', 'alpha', 'QWK'])}

ICC(2,1)/ICC(2,k): two-way random effects, absolute agreement; alpha: Krippendorff interval; QWK: mean over the 15 annotator pairs of quadratic-weighted kappa after binning into 0.5-wide bins. Clarity is the most reliable dimension and clinical_safety the least.

Hallucination flags (n = {n_items} items x 6 annotators):

{md_table(A3.assign(prevalence=A3.prevalence.round(3), pct_agree=A3.apply(lambda r: f(r.percent_agreement, r.percent_agreement_ci), axis=1), pairwise_kappa=A3.apply(lambda r: f(r.mean_pairwise_cohen_kappa, r.cohen_kappa_ci), axis=1), fleiss=A3.apply(lambda r: f(r.fleiss_kappa, r.fleiss_kappa_ci), axis=1), rare=A3.RARE_class_kappa_unstable.map({True: 'RARE: kappa unstable', False: ''})), ['class', 'prevalence', 'pct_agree', 'pairwise_kappa', 'fleiss', 'rare'])}

ANATOMICAL_CONFUSION has prevalence {a3.loc['ANATOMICAL_CONFUSION','prevalence']:.3f}: percent agreement is high ({a3.loc['ANATOMICAL_CONFUSION','percent_agreement']:.2f}) mostly because the class is rare, and its kappa should not be interpreted.

**By modality** (`A2`, `A4` tables): factual_correctness ICC(2,1) is {f(A2[(A2.dimension=='factual_correctness')].ICC2_1.min())}-{f(A2[(A2.dimension=='factual_correctness')].ICC2_1.max())} across modalities (ophthalmology lowest); flag kappa varies strongly by class and modality (e.g. OMISSION {f(A4[(A4['class']=='OMISSION')].mean_pairwise_cohen_kappa.min())}-{f(A4[(A4['class']=='OMISSION')].mean_pairwise_cohen_kappa.max())}).

**By annotator type** (pairs of annotators within each modality; specialist_own = the specialist for that modality, specialist_off = another modality's specialist):

{md_table(A5[A5.measure.isin(['factual_correctness','completeness','FLAGS'])].assign(value=lambda d: d.apply(lambda r: f(r.value, r.ci95), axis=1)).pivot(index='pair_type', columns='measure', values='value').reset_index())}

Specialists on their own modality do not agree more with the others on factual_correctness (own-non-specialist {f(by_type_fact.loc['specialist_own|non_specialist','value'], by_type_fact.loc['specialist_own|non_specialist','ci95'])} vs off-off {f(by_type_fact.loc['specialist_off|specialist_off','value'], by_type_fact.loc['specialist_off|specialist_off','ci95'])}; intervals overlap). Pairs of non-specialists agree least on completeness ({f(by_type_comp.loc['non_specialist|non_specialist','value'])}) and flags (kappa {f(by_type_flag.loc['non_specialist|non_specialist','value'])} vs {f(by_type_flag.loc['specialist_off|specialist_off','value'])} off-off).

**Caveats.** Fully crossed six-rater design: ICC(2,k) for six raters is high by construction; use ICC(2,1) for single-annotator reliability. Only one specialist exists per modality, so "specialist_own" pairs rest on one annotator per modality. No human annotator pool: see provenance above.

## B. Pipeline judge versus annotator majority
**Finding: against the annotator majority the combined pipeline reaches item-level any-hallucination F1 = {f(comb.loc['ALL','F1'], comb.loc['ALL','F1_ci'])} (target 0.90: not met at the point estimate, interval spans the target); the layer-wise targets (Layer 1 F1 >= 0.95, Layer 2 F1 >= 0.90) are not met, and class-level labels are weak.**

Majority label: a class is positive if at least 4 of 6 annotators flag it; a 3-3 tie ({H['B_ties_broken']} item-class cells) is resolved by the specialist of the item's modality. The comparison is at **item level**: annotators flag classes per item, so the judge's claim-level output is aggregated as "any claim of that class" (Layer-1 omissions counted as OMISSION, as in SMHR). n = {n_j} items.

Targets from the proposal, item-level any-hallucination (positive = any class flagged):

{md_table(B2.assign(F1=B2.apply(lambda r: f(r.F1, r.F1_ci), axis=1), precision=B2.precision.round(3), recall=B2.recall.round(3), kappa=B2.cohen_kappa.round(3)), ['scope', 'judge_output', 'n_items', 'precision', 'recall', 'F1', 'kappa', 'target_F1', 'target_met_point_estimate', 'target_met_lower_CI'])}

- Annotators flag at least one class on {int(comb.loc['ALL','human_any_positive'])} of {n_j} items ({comb.loc['ALL','human_any_positive']/n_j:.0%}), so Cohen's kappa for "any hallucination" is near zero ({f(comb.loc['ALL','cohen_kappa'])}) even when F1 is high; F1 and kappa answer different questions at this prevalence.
- "Layer 1" here is the Layer-1 omission/fabrication signal only, "Layer 2" any claim the judge marked as hallucinated; both are compared with the all-class human label, so the layer-wise rows are indicative rather than a strict test of each layer's own target.
- By modality the combined label meets 0.90 in radiology ({f(b2.loc[('radiology','combined_any (pipeline: any class)'),'F1'])}) and histopathology (point estimate {f(b2.loc[('histopathology','combined_any (pipeline: any class)'),'F1'])}, lower bound below the target), not in dermatology ({f(b2.loc[('dermatology','combined_any (pipeline: any class)'),'F1'])}) or ophthalmology ({f(b2.loc[('ophthalmology','combined_any (pipeline: any class)'),'F1'])}).

Per class (judge vs annotator majority):

{md_table(B1.assign(precision=B1.apply(lambda r: f(r.precision, r.precision_ci) if r.TP + r.FP else 'n/a', axis=1), recall=B1.apply(lambda r: f(r.recall, r.recall_ci), axis=1), F1=B1.apply(lambda r: f(r.F1, r.F1_ci) if r.F1 == r.F1 else 'undefined (0 TP)', axis=1), kappa=B1.apply(lambda r: f(r.cohen_kappa, r.kappa_ci), axis=1)), ['class', 'human_positive', 'judge_positive', 'precision', 'recall', 'F1', 'kappa'])}

Only FABRICATION (F1 {f(b1.loc['FABRICATION','F1'])}) is reasonably captured. OMISSION is over-called (precision {f(b1.loc['OMISSION','precision'])}); MISCLASSIFICATION, SEVERITY_DISTORTION and EVASION are rarely marked by the judge but often by annotators (recall {f(b1.loc['MISCLASSIFICATION','recall'])}, {f(b1.loc['SEVERITY_DISTORTION','recall'])}, {f(b1.loc['EVASION','recall'])}); ANATOMICAL_CONFUSION has 0 true positives out of {int(b1.loc['ANATOMICAL_CONFUSION','human_positive'])}. Primary-class exact agreement (highest-SMHR-weight class per item): {H['B_primary_class_exact_agreement']:.1%}. The target for the class-level claim is therefore **missed**, and class-specific SMHR contributions (classes 3-6) should not be described as validated.

Confusion matrices: `B3_confusion_cooccurrence_judge_by_human.csv` (judge class x human class co-occurrence) and `B4_primary_class_confusion.csv` (primary class). The 20 largest disagreements, with the modality specialist's own rationale as the reason, are in `B5_worst20_disagreements.csv`.

**Caveats.** Claim-level targets cannot be tested with item-level annotations; the proposal's thresholds may refer to claim-level F1. Items are clustered by image (see top box).

## C. SMHR class-weight sensitivity (12 models, {int(c2.loc['(i) assumed weights','n_images'])} images, benchmark-wide)
**Finding: the specialization paradox survives every weight set tested for the SRI part (all three specialists have SRI > 1 in all 12 specialist x modality cells in 100% of resamples under assumed, equal and all 200 perturbed weights), while "the three specialists rank worst" holds in {c2.loc['(iv) 200 random +/-30% perturbations','point_all_three_medical_rank_worst3']:.1%} of the 200 perturbations.**

{md_table(C2[~C2.weight_set.str.startswith('(ii)')].assign(rank_worst3=lambda d: d.apply(lambda r: f(r.boot_P_rank_worst3, r.boot_P_rank_worst3_ci), axis=1), sri_gt1=lambda d: d.apply(lambda r: f(r.boot_P_SRI_gt1, r.boot_P_SRI_gt1_ci), axis=1), both=lambda d: d.apply(lambda r: f(r.boot_P_both, r.boot_P_both_ci), axis=1), rho=lambda d: d.apply(lambda r: f(r.spearman_vs_assumed_boot_mean, r.spearman_boot_ci), axis=1), rho_min=lambda d: d.spearman_vs_assumed_point_min.round(3)), ['weight_set', 'n_weight_vectors', 'rank_worst3', 'sri_gt1', 'both', 'rho', 'rho_min'], rename={'rank_worst3': 'P(3 specialists = 3 worst) [CI]', 'sri_gt1': 'P(SRI>1 in all 12 cells) [CI]', 'both': 'P(both) [CI]', 'rho': 'Spearman vs assumed (boot mean) [CI]', 'rho_min': 'min Spearman (point)'})}

- (ii) **Clinician-elicited weights: not computed.** No clinician weight-elicitation data exists in the project or the repository, and no other statistic was substituted.
- The ranking is stable: Spearman with the assumed-weight ranking is {f(c2.loc['(iii) equal weights (all 1.0)','spearman_vs_assumed_point_mean'])} for equal weights and at least {f(c2.loc['(iv) 200 random +/-30% perturbations','spearman_vs_assumed_point_min'])} for every perturbation (mean {f(c2.loc['(iv) 200 random +/-30% perturbations','spearman_vs_assumed_point_mean'])}).
- The specialists' SMHR under the assumed weights: huatuogpt {C1.set_index('model').loc['huatuogpt','SMHR_assumed_weights']:.3f}, chexagent {C1.set_index('model').loc['chexagent','SMHR_assumed_weights']:.3f}, llava_med {C1.set_index('model').loc['llava_med','SMHR_assumed_weights']:.3f}, versus llava16 (the worst general model) {C1.set_index('model').loc['llava16','SMHR_assumed_weights']:.3f}; the gap to llava16 is small for huatuogpt, which is why some perturbations reorder them.

**Caveats.** This tests the class weights only; it does not test the labels (see B). Bootstrap resamples images (3,500) with the same resample for all models; perturbations multiply each weight by U(0.7, 1.3) independently (seed 42).

## D. Annotator-role comparison
*(The annotators are compared by their stated roles; see the provenance statement at the top.)*

**Finding: the annotators rank items almost identically (Spearman of each annotator's overall score with the mean of the other five: {f(D3.spearman_overall_vs_mean_of_other_five.min(),None,2)}-{f(D3.spearman_overall_vs_mean_of_other_five.max(),None,2)}), but their levels differ: the dermatology specialist rates its own modality higher, the radiology specialist lower, and the student is more lenient.**

- Specialist vs the other five annotators on the specialist's own modality (Wilcoxon signed-rank, Holm-corrected across 24 tests): {len(sig)} of 24 tests are significant at 0.05. Dermatology specialist, factual_correctness: {derm_f.mean_diff:+.3f} [{ci(derm_f.diff_ci95)[0]:+.3f}, {ci(derm_f.diff_ci95)[1]:+.3f}] (Holm p {derm_f.holm_p_24_tests:.4f}, n = {int(derm_f.n_items)}); radiology specialist, clinical_safety: {rad_s.mean_diff:+.3f} [{ci(rad_s.diff_ci95)[0]:+.3f}, {ci(rad_s.diff_ci95)[1]:+.3f}] (Holm p {rad_s.holm_p_24_tests:.4f}). The direction is not consistent across specialists, so there is no general "specialists are stricter on their own modality" effect. Full table: `D2_specialist_own_modality_vs_others_wilcoxon.csv`.
- Student vs specialists: agreement with the own-modality specialist is lower on factual_correctness (ICC(2,1) {f(d4.loc['factual_correctness','student_vs_own_modality_specialist_ICC2_1'], d4.loc['factual_correctness','icc_ci'])}) than on clarity ({f(d4.loc['clarity','student_vs_own_modality_specialist_ICC2_1'], d4.loc['clarity','icc_ci'])}), the pattern predicted for a non-specialist; the flag kappa against the majority of the other five is also lowest for the student ({f(d3.loc['undergrad_student','kappa_flags_vs_majority_of_other_five_mean_over_classes'], d3.loc['undergrad_student','kappa_ci'])} vs {f(d3.kappa_flags_vs_majority_of_other_five_mean_over_classes.drop('undergrad_student').min())}-{f(d3.kappa_flags_vs_majority_of_other_five_mean_over_classes.drop('undergrad_student').max())} for the others).
- Leniency: the student scores higher than the mean of the other five on overall by {stu.loc['overall','student_minus_mean_of_other_five']:+.3f} [{ci(stu.loc['overall','leniency_ci'])[0]:+.3f}, {ci(stu.loc['overall','leniency_ci'])[1]:+.3f}] (largest on informativeness, {stu.loc['informativeness','student_minus_mean_of_other_five']:+.3f}); Bland-Altman bias and limits of agreement for every annotator are in `D5_leniency_bland_altman.csv`.
- Tracking the pipeline's item SMHR (n = {int(D6.n_items.iloc[0])}): Spearman between each annotator's factual_correctness and item SMHR is {f(D6.spearman_factual_vs_item_SMHR.max(),None,2)} to {f(D6.spearman_factual_vs_item_SMHR.min(),None,2)} (all intervals exclude 0): moderate and in the expected direction. Agreement of each annotator's any-hallucination flag with the judge is near zero in kappa ({f(d3.kappa_any_hallucination_vs_judge.min(),None,2)}-{f(d3.kappa_any_hallucination_vs_judge.max(),None,2)}) because of the 87% prevalence (see B).

**Caveats.** One annotator per role; differences between roles cannot be separated from differences between individual annotators. The persona-study sub-questions that need a separate set of AI annotators could not be run, because no separate AI set exists (the AI-persona files are the same records).

## E. Do annotator scores track the benchmark metric?
**Finding: the mean annotator factual_correctness correlates modestly and negatively with the item-level SMHR (Spearman {f(e1.loc['ALL','spearman_mean_factual_vs_item_SMHR'], e1.loc['ALL','ci95'])}, n = {int(e1.loc['ALL','n_items'])}), strongest in dermatology and absent in histopathology.**

{md_table(E1.assign(rho=E1.apply(lambda r: f(r.spearman_mean_factual_vs_item_SMHR, r.ci95), axis=1), p=E1.p_value.map(lambda v: f'{v:.4f}')), ['scope', 'n_items', 'n_excluded_no_claims', 'rho', 'p'])}

Items whose response has no claims (item SMHR undefined) are excluded. A moderate correlation is the expected size when SMHR is a claim-weighted ratio and the score is a holistic rating. Histopathology's interval includes 0, so no relationship can be claimed there.

## Files
`annotation_results/*.csv` (one per table), `annotation_results/headline_numbers.json`, `annotation_analysis.py`, `build_annotation_report.py`, `annotation_paper_paragraphs.tex`.
"""
(ROOT / 'annotation_report.md').write_text(report, encoding='utf-8')

tex = r"""%% Draft paragraphs for the validation section. Replace the PROVENANCE placeholder before use.
\paragraph{Annotation set.}
Six annotators rated 720 generated texts (180 per modality, five models, three conditions, 48 images): a generalist, four modality
specialists (radiology, dermatology, histopathology, ophthalmology) and an undergraduate student, each on six 0--5 scales and seven
hallucination-class flags. \textbf{[PROVENANCE: state here exactly who produced these annotations and under what protocol; the files analysed
were generated by language-model personas according to the repository history.]}
Because the 720 items rest on 48 distinct images, intervals that resample items treat clustered items as independent and are optimistic.

\paragraph{Agreement.}
Agreement on the scores was high: single-rater ICC(2,1) ranged from %(icc_min).2f (clinical safety) to %(icc_max).2f (clarity), with
ICC(2,k) $\geq %(icck_min).2f$ for six raters. Agreement on the flags was moderate and class dependent: pairwise Cohen's $\kappa$ was %(k_fab).2f for
fabrication and %(k_eva).2f for evasion, but only %(k_omi).2f for omission, %(k_ana).2f for anatomical confusion (prevalence %(p_ana).1f\%%, so $\kappa$ is
unstable) and %(k_cre).2f for clinical-reasoning error. Specialists did not agree more with the other annotators on their own modality than off it.

\paragraph{Validation of the automatic pipeline.}
Against the annotator-majority label (class positive if flagged by at least four of six annotators; ties broken by the modality specialist),
the pipeline's item-level any-hallucination label reached $F_1 = %(f1)s$ ($n=%(nj)d$ items), marginally below the 0.90 target, and met the target in
radiology ($F_1 = %(f1_rad).2f$) but not in dermatology ($%(f1_der).2f$) or ophthalmology ($%(f1_oph).2f$). The comparison is made at item level because annotators
flagged items rather than claims. Class-level agreement was weak: $F_1$ was %(f1_fab).2f for fabrication and %(f1_omi).2f for omission (precision %(p_omi).2f), and the
judge rarely marked misclassification, severity distortion or evasion (recall %(r_mis).2f, %(r_sev).2f and %(r_eva).2f). The Layer-1 and Layer-2 $F_1$ targets (0.95 and 0.90) were not met.
We therefore do not claim validation of the class-specific labels.

\paragraph{Robustness of SMHR to the class weights.}
Recomputing SMHR for all twelve models under equal weights and 200 random $\pm30\%%$ perturbations of the assumed weights left the model ranking
essentially unchanged (Spearman $\rho \geq %(rho_min).2f$ against the assumed-weight ranking). Every medical specialist had SRI $>1$ in every modality
under every weight set, and the three specialists occupied the three worst ranks in %(pw3).1f\%% of the perturbations. Clinician-elicited weights were not available, so
the weights themselves are not independently validated.
"""
vals = dict(
    icc_min=A1.ICC2_1.min(), icc_max=A1.ICC2_1.max(), icck_min=A1.ICC2_k.min(),
    k_fab=a3.loc['FABRICATION', 'mean_pairwise_cohen_kappa'], k_eva=a3.loc['EVASION', 'mean_pairwise_cohen_kappa'],
    k_omi=a3.loc['OMISSION', 'mean_pairwise_cohen_kappa'], k_ana=a3.loc['ANATOMICAL_CONFUSION', 'mean_pairwise_cohen_kappa'],
    p_ana=100 * a3.loc['ANATOMICAL_CONFUSION', 'prevalence'], k_cre=a3.loc['CLINICAL_REASONING_ERROR', 'mean_pairwise_cohen_kappa'],
    f1='%.3f$ [%.3f, %.3f]' % (comb.loc['ALL', 'F1'], *ci(comb.loc['ALL', 'F1_ci'])), nj=n_j,
    f1_rad=b2.loc[('radiology', 'combined_any (pipeline: any class)'), 'F1'], f1_der=b2.loc[('dermatology', 'combined_any (pipeline: any class)'), 'F1'],
    f1_oph=b2.loc[('ophthalmology', 'combined_any (pipeline: any class)'), 'F1'], f1_fab=b1.loc['FABRICATION', 'F1'], f1_omi=b1.loc['OMISSION', 'F1'],
    p_omi=b1.loc['OMISSION', 'precision'], r_mis=b1.loc['MISCLASSIFICATION', 'recall'], r_sev=b1.loc['SEVERITY_DISTORTION', 'recall'], r_eva=b1.loc['EVASION', 'recall'],
    rho_min=c2.loc['(iv) 200 random +/-30% perturbations', 'spearman_vs_assumed_point_min'],
    pw3=100 * c2.loc['(iv) 200 random +/-30% perturbations', 'point_all_three_medical_rank_worst3'])
(ROOT / 'annotation_paper_paragraphs.tex').write_text(tex % vals, encoding='utf-8')
print('wrote annotation_report.md and annotation_paper_paragraphs.tex')
